 static void Capture(Form f,string name){using var image=new Bitmap(f.Width,f.Height);f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save("integration-evidence/"+name+".png");}
 static void Chooser(Form sales,Action<Form> check){Exception? failure=null;bool seen=false;using var timer=new System.Windows.Forms.Timer{Interval=40};timer.Tick+=(_,_)=>{var f=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text=="Estilo da Tela de Vendas");if(f==null||seen)return;seen=true;timer.Stop();try{SalesStyles.Observe();check(f);}catch(Exception e){failure=e;}finally{if(!f.IsDisposed)f.Close();}};timer.Start();All(sales).OfType<Button>().Single(x=>x.Text.Contains("ESTILO")).PerformClick();Check(seen&&failure==null,"Chooser failed: "+failure);}
 static void Sales(MainForm main,Action<Form> check){bool seen=false;Exception? failure=null;using var timer=new System.Windows.Forms.Timer{Interval=50};timer.Tick+=(_,_)=>{var f=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x.Text.Contains("TELA DE VENDAS"));if(f==null||seen)return;seen=true;timer.Stop();try{SalesStyles.Observe();check(f);}catch(Exception e){failure=e;}finally{f.Close();}};timer.Start();MainType.GetMethod("OpenSales",I)!.Invoke(main,null);Check(seen&&failure==null,"Actual sales form failed: "+failure);}
 static void Blue(Form f){Check(Get("sales_theme")=="Azul Texturizado","Selection not persisted");Check(f.BackgroundImage!=null,"Texture missing");Check(f.BackColor==Color.FromArgb(3,18,38),"Blue palette missing");using var original=new Bitmap("Assets/tema_azul_texturizado.jpg");using var actual=new Bitmap(f.BackgroundImage!);Check(actual.Size==original.Size,"Texture size mismatch");for(int y=0;y<actual.Height;y+=Math.Max(1,actual.Height/10))for(int x=0;x<actual.Width;x+=Math.Max(1,actual.Width/10))Check(actual.GetPixel(x,y)==original.GetPixel(x,y),"Different original texture");var grid=All(f).OfType<DataGridView>().Single();Check(grid.BackgroundColor==Color.FromArgb(3,18,38),"Grid palette mismatch");Check(grid.GetType().GetProperty("ThemeTexture",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.GetValue(grid)!=null,"Grid texture missing");}
 [STAThread]static void Main(string[] args){
 Check(Environment.GetEnvironmentVariable("GITHUB_ACTIONS")=="true","Disposable runner only");_ = Task.Run(async()=>{await Task.Delay(120000);Environment.Exit(1);});Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();Directory.CreateDirectory("integration-evidence");
 LealInfoPDV.Database.Initialize();Sql("INSERT OR REPLACE INTO settings(key,value) VALUES('company_registered','1'),('security_setup_completed','1'),('first_access_tutorial_completed','1'),('company_name','ANGRA QA FIXTURE'),('company_city_state','Angra dos Reis/RJ')");
 Auth.CreateUser("QA","qa","Synthetic-QA-Only!","ADMINISTRADOR","qa@example.invalid","");Check(Auth.Login("qa","Synthetic-QA-Only!")!=null,"Fixture login failed");
 var a=typeof(MainForm).Assembly;a.GetType("LealInfoPDV.Licensing.InstallationLicense")!.GetProperty("Current",S)!.SetValue(null,new LicenseTerms("QA",2,"unico",null,"",1,"QA","standard","TESTE"));
 using var main=new MainForm();main.Show();Pump();((System.Windows.Forms.Timer)MainType.GetField("licenseTimer",I)!.GetValue(main)!).Stop();MainType.GetField("automaticBackupCompleted",I)!.SetValue(main,true);
 Assembly.LoadFrom(Path.GetFullPath(args[0]));
 Sales(main,f=>{Check(Get("angra_qa005_sales_style")=="","Changed default without selection");Chooser(f,c=>{var cards=All(c).OfType<Button>().Where(b=>b.Tag is string).ToArray();Check(cards.Length==6,"Expected six styles");Check(cards.Select(x=>(string)x.Tag!).Distinct().Count()==6,"Duplicate style");Capture(c,"six-style-selector");cards.Single(x=>(string)x.Tag! =="Azul Texturizado").PerformClick();});Blue(f);Capture(f,"blue-textured-sales");
 foreach(var name in new[]{"Futurista Azul","Dark Premium","Clean Pro","Blue Red Racing","PDV Rosa"}){Chooser(f,c=>All(c).OfType<Button>().Single(x=>x.Tag is string t&&t==name).PerformClick());Check(Get("sales_theme")==name,"Original style broken: "+name);Check(Get("angra_qa005_sales_style")==name,"QA preference not cleared");if(name!="PDV Rosa")Check(f.BackgroundImage==null,"Blue texture leaked into "+name);}
 Chooser(f,c=>All(c).OfType<Button>().Single(x=>x.Tag is string t&&t=="Azul Texturizado").PerformClick());Blue(f);});
 Sales(main,f=>{Blue(f);Capture(f,"blue-textured-reopened");});main.Close();Console.WriteLine("PASS actual sales selector: six options, exact Loja texture, existing five styles, persistence and reopening");
 }
